SELECT 'interest_income_inr' AS component,(SELECT MAX(month) FROM cc_monthly_financials) AS current_month,(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) AS previous_month,1*(SUM(CASE WHEN month=(SELECT MAX(month) FROM cc_monthly_financials) THEN interest_income_inr ELSE 0 END)-SUM(CASE WHEN month=(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) THEN interest_income_inr ELSE 0 END)) AS profit_change_inr FROM cc_monthly_financials
UNION ALL
SELECT 'fee_income_inr' AS component,(SELECT MAX(month) FROM cc_monthly_financials) AS current_month,(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) AS previous_month,1*(SUM(CASE WHEN month=(SELECT MAX(month) FROM cc_monthly_financials) THEN fee_income_inr ELSE 0 END)-SUM(CASE WHEN month=(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) THEN fee_income_inr ELSE 0 END)) AS profit_change_inr FROM cc_monthly_financials
UNION ALL
SELECT 'interchange_income_inr' AS component,(SELECT MAX(month) FROM cc_monthly_financials) AS current_month,(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) AS previous_month,1*(SUM(CASE WHEN month=(SELECT MAX(month) FROM cc_monthly_financials) THEN interchange_income_inr ELSE 0 END)-SUM(CASE WHEN month=(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) THEN interchange_income_inr ELSE 0 END)) AS profit_change_inr FROM cc_monthly_financials
