SELECT 'credit_cost_inr' AS component,(SELECT MAX(month) FROM cc_monthly_financials) AS current_month,(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) AS previous_month,-1*(SUM(CASE WHEN month=(SELECT MAX(month) FROM cc_monthly_financials) THEN credit_cost_inr ELSE 0 END)-SUM(CASE WHEN month=(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) THEN credit_cost_inr ELSE 0 END)) AS profit_change_inr FROM cc_monthly_financials
UNION ALL
SELECT 'fixed_opex_inr' AS component,(SELECT MAX(month) FROM cc_monthly_financials) AS current_month,(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) AS previous_month,-1*(SUM(CASE WHEN month=(SELECT MAX(month) FROM cc_monthly_financials) THEN fixed_opex_inr ELSE 0 END)-SUM(CASE WHEN month=(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) THEN fixed_opex_inr ELSE 0 END)) AS profit_change_inr FROM cc_monthly_financials
UNION ALL
SELECT 'variable_opex_inr' AS component,(SELECT MAX(month) FROM cc_monthly_financials) AS current_month,(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) AS previous_month,-1*(SUM(CASE WHEN month=(SELECT MAX(month) FROM cc_monthly_financials) THEN variable_opex_inr ELSE 0 END)-SUM(CASE WHEN month=(SELECT MAX(month)-INTERVAL '1 month' FROM cc_monthly_financials) THEN variable_opex_inr ELSE 0 END)) AS profit_change_inr FROM cc_monthly_financials
